def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression string.

    Supports: integers, decimals, +, -, *, /, %, **, parentheses, unary +/-
    Precedence (loosest to tightest): + -, * / %, **, unary +/-
    ** is right-associative.
    """

    class Tokenizer:
        def __init__(self, text: str):
            self.text = text
            self.pos = 0
            self.tokens = []
            self._tokenize()
            self.idx = 0

        def _tokenize(self):
            text = self.text
            n = len(text)
            i = 0
            tokens = []
            while i < n:
                c = text[i]
                if c.isspace():
                    i += 1
                    continue
                if c in '+-*/%()':
                    tokens.append(c)
                    i += 1
                elif c == '=':
                    # Not expected in arithmetic expressions
                    raise ValueError(f"Unexpected character '=' at position {i}")
                elif c.isdigit() or c == '.':
                    # Parse number
                    start = i
                    has_dot = (c == '.')
                    i += 1
                    while i < n and (text[i].isdigit() or (text[i] == '.' and not has_dot)):
                        if text[i] == '.':
                            has_dot = True
                        i += 1
                    num_str = text[start:i]
                    if has_dot:
                        tokens.append(float(num_str))
                    else:
                        tokens.append(int(num_str))
                else:
                    raise ValueError(f"Unexpected character '{c}' at position {i}")
            self.tokens = tokens

        def peek(self):
            if self.idx < len(self.tokens):
                return self.tokens[self.idx]
            return None

        def consume(self):
            tok = self.tokens[self.idx]
            self.idx += 1
            return tok

        def expect(self, val):
            tok = self.peek()
            if tok != val:
                raise ValueError(f"Expected '{val}', got '{tok}'")
            return self.consume()

        def is_end(self):
            return self.idx >= len(self.tokens)

    class Parser:
        def __init__(self, tokens: list):
            self.tokens = tokens
            self.idx = 0

        def peek(self):
            if self.idx < len(self.tokens):
                return self.tokens[self.idx]
            return None

        def consume(self):
            tok = self.tokens[self.idx]
            self.idx += 1
            return tok

        def is_end(self):
            return self.idx >= len(self.tokens)

        def parse(self):
            result = self.parse_add_sub()
            if not self.is_end():
                raise ValueError(f"Unexpected token '{self.peek()}' after expression")
            return result

        def parse_add_sub(self):
            left = self.parse_mul_div_mod()
            while not self.is_end() and self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_mul_div_mod()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_mul_div_mod(self):
            left = self.parse_power()
            while not self.is_end() and self.peek() in ('*', '/', '%'):
                op = self.consume()
                right = self.parse_power()
                if op == '*':
                    left = left * right
                elif op == '/':
                    if right == 0:
                        raise ValueError("Division by zero")
                    left = left / right
                else:  # '%'
                    if right == 0:
                        raise ValueError("Modulo by zero")
                    left = left % right
            return left

        def parse_power(self):
            # ** is right-associative
            base = self.parse_unary()
            if not self.is_end() and self.peek() == '**':
                self.consume()  # consume **
                exponent = self.parse_power()  # right-associative: parse_power calls parse_unary which handles unary minus
                return base ** exponent
            return base

        def parse_unary(self):
            tok = self.peek()
            if tok == '-':
                self.consume()
                operand = self.parse_unary()
                return -operand
            elif tok == '+':
                self.consume()
                operand = self.parse_unary()
                return operand
            else:
                return self.parse_primary()

        def parse_primary(self):
            tok = self.peek()
