    def __init__(self):
        self.root = {}
        self.words = set()

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['#'] = True
        self.words.add(word)

    def remove(self, word):
        if word not in self.words:
            return False
        node = self.root
        for char in word:
            if char not in node:
                return False
            node = node[char]
        if '#' in node:
            del node['#']
            # Clean up empty nodes if needed, but not strictly required for correctness
            # However, to keep the trie clean, we could remove empty nodes
            # But for simplicity and correctness, we just mark end
            self.words.discard(word)
            return True
        return False

    def search(self, pattern):
        results = []
        self._search_helper(self.root, pattern, 0, "", results)
        return sorted(results)

    def _search_helper(self, node, pattern, index, current_word, results):
        if index == len(pattern):
            if '#' in node:
                results.append(current_word)
            return

        char = pattern[index]
        if char == '.':
            for next_char in node:
                if next_char == '#':
                    continue
                self._search_helper(node[next_char], pattern, index + 1, current_word + next_char, results)
        else:
            if char in node:
                self._search_helper(node[char], pattern, index + 1, current_word + char, results)
