def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    base = len(alphabet)
    if alphabet[0] != '0':
        raise ValueError("First character of alphabet must be '0'")

    if n == 0:
        return alphabet[0]

    negative = False
    if n < 0:
        negative = True
        n = -n

    digits = []
    while n > 0:
        n, remainder = divmod(n, base)
        digits.append(alphabet[remainder])

    if negative:
        digits.append('-')

    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("String must not be empty")

    base = len(alphabet)
    if alphabet[0] != '0':
        raise ValueError("First character of alphabet must be '0'")

    # Create a mapping from character to value
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}

    negative = False
    start = 0
    if s[0] == '-':
        negative = True
        start = 1
        if start >= len(s):
            raise ValueError("Empty string after sign")

    result = 0
    for i in range(start, len(s)):
        ch = s[i]
        if ch not in char_to_val:
            raise ValueError(f"Character '{ch}' not in alphabet")
        result = result * base + char_to_val[ch]

    if negative:
        result = -result

    return result
