        # Store the old state for rollback
        old_value = self._cells.get(cell)
        old_dependents = self._dependents.get(cell, set()).copy()
        old_cache_val = self._cache.get(cell)

        # Remove old dependencies from dependents map
        if old_value is not None:
            self._remove_dependencies(cell)

        # Parse the new value
        if isinstance(value, str) and value.startswith('='):
            formula_str = value[1:]
            parsed = self._parse_formula(formula_str)
            if parsed is None:
                # Invalid formula, rollback
                self._cells[cell] = old_value
                if old_value is not None:
                    self._add_dependencies(cell, old_value)
                if old_cache_val is not None:
                    self._cache[cell] = old_cache_val
                return

            self._cells[cell] = value
            self._formula_map[cell] = parsed
        else:
            self._cells[cell] = value
            if cell in self._formula_map:
                del self._formula_map[cell]

        # Check for cycles using DFS
        if self._has_cycle(cell):
            # Rollback
            self._cells[cell] = old_value
            if old_value is not None:
                self._add_dependencies(cell, old_value)
            if old_cache_val is not None:
                self._cache[cell] = old_cache_val
            # Clear dependents for this cell if it was added
            if cell in self._dependents:
                del self._dependents[cell]
            raise ValueError("Reference cycle detected")

        # Add new dependencies
        if isinstance(value, str) and value.startswith('='):
            self._add_dependencies(cell, value)

        # Invalidate cache for this cell and all transitive dependents
        self._invalidate_cache(cell)

    def get(self, cell):
        if cell not in self._cells:
            return 0

        # If cached, return it
        if cell in self._cache:
            return self._cache[cell]

        # Compute value
        val = self._compute_value(cell)
        self._cache[cell] = val
        return val

    def _parse_formula(self, formula_str):
        """Parse formula string into a list of (operator, operand) tuples.
        Operands are either 'LITERAL' with a number or 'CELL' with a cell ID.
        Returns None if parsing fails."""
        try:
            tokens = self._tokenize(formula_str)
            if not tokens:
                return None
            return self._parse_expression(tokens, 0)[0]
        except:
            return None

    def _tokenize(self, formula_str):
        tokens = []
        i = 0
        n = len(formula_str)
        while i < n:
            if formula_str[i].isspace():
                i += 1
                continue
            if formula_str[i] in '+-*':
                tokens.append(('OP', formula_str[i]))
                i += 1
            elif formula_str[i].isdigit():
                j = i
                while j < n and formula_str[j].isdigit():
                    j += 1
                tokens.append(('LITERAL', int(formula_str[i:j])))
                i = j
            elif formula_str[i].isalpha():
                j = i
                while j < n and (formula_str[j].isalnum() or formula_str[j] == '$'):
                    j += 1
                tokens.append(('CELL', formula_str[i:j]))
                i = j
            else:
                return None  # Invalid character
        return tokens

    def _parse_expression(self, tokens, pos):
        """Parse expression with + and - (lowest precedence).
        Returns (value, next_pos)."""
        left, pos = self._parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in '+-':
            op = tokens[pos][1]
            pos += 1
            right, pos = self._parse_term(tokens, pos)
            if op == '+':
                left = ('ADD', left, right)
            else:
                left = ('SUB', left, right)
        return left, pos

    def _parse_term(self, tokens, pos):
        """Parse term with * (higher precedence).
        Returns (value, next_pos)."""
        left, pos = self._parse_factor(tokens, pos)
        while pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] == '*':
            pos += 1
            right, pos = self._parse_factor(tokens, pos)
            left = ('MUL', left, right)
        return left, pos

    def _parse_factor(self, tokens, pos):
        """Parse factor (literal or cell).
        Returns (value, next_pos)."""
        if pos >= len(tokens):
            return None, pos
        token_type, token_val = tokens[pos]
        if token_type == 'LITERAL':
            return ('LITERAL', token_val), pos + 1
        elif token_type == 'CELL':
            return ('CELL', token_val), pos + 1
        else:
            return None, pos

    def _add_dependencies(self, cell, raw_value):
        """Add dependencies from a cell to its referenced cells."""
        if cell not in self._dependents:
            self._dependents[cell] = set()

        if isinstance(raw_value, str) and raw_value.startswith('='):
            parsed = self._formula_map.get(cell)
            if parsed:
                self._collect_cell_refs(parsed, self._dependents[cell])

    def _remove_dependencies(self, cell):
        """Remove dependencies from a cell."""
        if cell in self._dependents:
            for dep in self._dependents[cell]:
                if dep in self._dependents and cell in self._dependents[dep]:
                    self._dependents[dep].discard(cell)
            del self._dependents[cell]
        if cell in self._formula_map:
            del self._formula_map[cell]

    def _collect_cell_refs(self, node, refs):
        """Collect all cell references from a parsed formula node."""
        if node is None:
            return
        if node[0] == 'CELL':
            refs.add(node[1])
        elif node[0] in ('ADD', 'SUB', 'MUL'):
            self._collect_cell_refs(node[1], refs)
            self._collect_cell_refs(node[2], refs)

    def _has_cycle(self, start_cell):
        """Check if setting start_cell creates a cycle."""
        # We need to check if start_cell is reachable from any of its dependencies
        # via the existing dependency graph.
        # If start_cell depends on A, and A depends on B, and B depends on start_cell,
        # then there's a cycle.

        # Get direct dependencies of start_cell
        deps = self._dependents.get(start_cell, set())
        if not deps:
            return False

        # DFS from each dependency to see if we can reach start_cell
        visited = set()
        stack = list(deps)
        while stack:
            current = stack.pop()
            if current == start_cell:
                return True
            if current in visited:
                continue
            visited.add(current)
            # Add dependents of current to stack
            if current in self._dependents:
                stack.extend(self._dependents[current])
        return False

    def _invalidate_cache(self, cell):
        """Invalidate cache for cell and all transitive dependents."""
        if cell in self._cache:
            del self._cache[cell]

        # Invalidate all dependents
        if cell in self._dependents:
            for dep in self._dependents[cell]:
                self._invalidate_cache(dep)

    def _compute_value(self, cell):
        """Compute the value of a cell."""
        raw = self._cells.get(cell)
        if raw is None:
            return 0

        if isinstance(raw, (int, float)):
            return float(raw) if isinstance(raw, int) else raw

        # It's a formula
        parsed = self._formula_map.get(cell)
        if parsed is None:
            return 0

        return self._evaluate(parsed)

    def _evaluate(self, node):
        """Evaluate a parsed formula node."""
        if node is None:
            return 0

        if node[0] == 'LITERAL':
            return float(node[1])
        elif node[0] == 'CELL':
            cell_id = node[1]
            return self.get(cell_id)
        elif node[0] == 'ADD':
            return self._evaluate(node[1]) + self._evaluate(node[2])
        elif node[0] == 'SUB':
            return self._evaluate(node[1]) - self._evaluate(node[2])
        elif node[0] == 'MUL':
            return self._evaluate(node[1]) * self._evaluate(node[2])
        else:
            return 0
