function deepEqual(a, b) {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  const seen = new WeakMap();

  function compare(x, y) {
    if (x === y) return true;
    if (x === null || y === null || typeof x !== typeof y) return false;

    // Handle NaN
    if (Number.isNaN(x) && Number.isNaN(y)) return true;

    // Handle primitives
    if (typeof x !== 'object') return false;

    // Handle Date
    if (x instanceof Date) {
      return x.getTime() === y.getTime();
    }

    // Handle RegExp
    if (x instanceof RegExp) {
      return x.source === y.source && x.flags === y.flags;
    }

    // Handle Map
    if (x instanceof Map) {
      if (!(y instanceof Map)) return false;
      if (x.size !== y.size) return false;
      for (const [key, val] of x) {
        if (!hasMapKey(y, key, val, compare, seen)) return false;
      }
      return true;
    }

    // Handle Set
    if (x instanceof Set) {
      if (!(y instanceof Set)) return false;
      if (x.size !== y.size) return false;
      for (const val of x) {
        if (!hasSetValue(y, val, compare, seen)) return false;
      }
      return true;
    }

    // Handle Arrays
    if (Array.isArray(x)) {
      if (!Array.isArray(y)) return false;
      if (x.length !== y.length) return false;
      for (let i = 0; i < x.length; i++) {
        if (!compare(x[i], y[i])) return false;
      }
      return true;
    }

    // Handle Objects (including plain objects and custom objects)
    const keysX = Object.keys(x);
    const keysY = Object.keys(y);

    if (keysX.length !== keysY.length) return false;

    for (const key of keysX) {
      if (!Object.prototype.hasOwnProperty.call(y, key)) return false;
      if (!compare(x[key], y[key])) return false;
    }

    return true;
  }

  // Helper for Map keys (handling NaN and cycles)
  function hasMapKey(map, key, val, compare, seen) {
    for (const [k, v] of map) {
      if (compare(k, key)) {
        return compare(val, v);
      }
    }
    return false;
  }

  // Helper for Set values (handling NaN and cycles)
  function hasSetValue(set, val, compare, seen) {
    for (const v of set) {
      if (compare(val, v)) return true;
    }
    return false;
  }

  return compare(a, b);
}

