function pLimit(n) {
  let active = 0;
  const queue = [];

  function run() {
    if (queue.length === 0 || active >= n) {
      return;
    }

    const { fn, resolve, reject } = queue.shift();
    active++;

    const promise = fn();
    promise.then(
      (result) => {
        active--;
        resolve(result);
        run();
      },
      (error) => {
        active--;
        reject(error);
        run();
      }
    );
  }

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      run();
    });
  };
}

module.exports = pLimit;
