function debounce(fn, wait, options = {}) {
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let lastResult = null;
  let lastCallTime = null;
  let lastInvokeTime = 0;
  let leading = options.leading === true;
  let trailing = options.trailing !== false;

  function invokeFunc(time) {
    const args = lastArgs;
    const thisArg = lastThis;
    lastArgs = lastThis = null;
    lastResult = fn.apply(thisArg, args);
    lastInvokeTime = time;
    return lastResult;
  }

  function leadingEdge(time) {
    lastInvokeTime = time;
    timeoutId = setTimeout(trailingEdge, wait);
    return invokeFunc(time);
  }

  function getRemainingTime() {
    const timeNow = Date.now();
    const remaining = wait - (timeNow - lastCallTime);
    return remaining > 0 ? remaining : 0;
  }

  function shouldInvoke(time) {
    const timeNow = Date.now();
    const timeSinceLastCall = timeNow - lastCallTime;
    const timeSinceLastInvoke = timeNow - lastInvokeTime;
    return lastCallTime === undefined || timeSinceLastCall >= wait || timeSinceLastInvoke < 0 || (wait < timeSinceLastCall && timeSinceLastInvoke > wait);
  }

  function trailingEdge(time) {
    timeoutId = null;
    if (trailing && lastArgs) {
      return invokeFunc(time);
    }
    lastArgs = lastThis = null;
    return lastResult;
  }

  function timerExpired() {
    const time = Date.now();
    if (shouldInvoke(time)) {
      return trailingEdge(time);
    }
    timeoutId = setTimeout(timerExpired, getRemainingTime());
  }

  function cancel() {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    lastArgs = lastThis = lastCallTime = lastInvokeTime = null;
    lastResult = null;
  }

  function flush() {
    if (timeoutId !== null) {
      const result = trailingEdge(Date.now());
      timeoutId = null;
      return result;
    }
    return lastResult;
  }

  function debounced(...args) {
    const time = Date.now();
    const isInvoking = shouldInvoke(time);

    lastArgs = args;
    lastThis = this;
    lastCallTime = time;

    if (isInvoking) {
      if (timeoutId === null) {
        if (leading) {
          return leadingEdge(time);
        } else {
          timeoutId = setTimeout(timerExpired, wait);
        }
      } else {
        if (leading) {
          clearTimeout(timeoutId);
          timeoutId = setTimeout(timerExpired, wait);
          return invokeFunc(time);
        }
      }
    }

    if (timeoutId === null && leading) {
       timeoutId = setTimeout(timerExpired, wait);
    }

    return lastResult;
  }

