class Emitter {
  constructor() {
    this._listeners = {};
  }

  on(event, fn) {
    if (!this._listeners[event]) {
      this._listeners[event] = [];
    }
    const listener = { fn, once: false };
    this._listeners[event].push(listener);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn(...args);
    };
    wrapper._original = fn;
    return this.on(event, wrapper);
  }

  off(event, fn) {
    if (!this._listeners[event]) return;
    const listeners = this._listeners[event];
    for (let i = 0; i < listeners.length; i++) {
      const listener = listeners[i];
      if (listener.fn === fn || listener.fn._original === fn) {
        listeners.splice(i, 1);
        i--;
      }
    }
  }

  emit(event, ...args) {
    if (!this._listeners[event]) return 0;

    // Snapshot current listeners to handle dynamic additions/removals
    const listeners = [...this._listeners[event]];
    let invokedCount = 0;
    let firstError = null;

    for (const listener of listeners) {
      // Skip if removed during emit (check if still in current active list)
      // Since we are iterating a snapshot, we need to check if the listener
      // is still valid in the original _listeners[event] array.
      // However, the requirement says "removed during an emit must not be invoked".
      // The snapshot approach handles additions. For removals, we check existence.

      // Check if the listener is still in the active listeners list
      const isActive = this._listeners[event].some(
        l => l.fn === listener.fn
      );

      if (!isActive) continue;

      try {
        listener.fn(...args);
        invokedCount++;
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return invokedCount;
  }
}

module.exports = Emitter;
