      const oldPlaceholderRegex = /\$([0-9]+)/g;

      let inlinedText = val.text.replace(oldPlaceholderRegex, (match, num) => {
        const originalIndex = parseInt(num, 10);
        const newPlaceholder = `$${originalIndex + placeholderCounter}`;
        return newPlaceholder;
      });

      text += inlinedText;

      // Merge values, renumbering them
      for (let i = 0; i < val.values.length; i++) {
        resultValues.push(val.values[i]);
      }

      // Update the global counter to account for the inlined placeholders
      placeholderCounter += originalPlaceholderCount;
    } else if (Array.isArray(val)) {
      // Array becomes parenthesized comma-separated list
      if (val.length === 0) {
        text += '(NULL)';
      } else {
        text += '(';
        for (let i = 0; i < val.length; i++) {
          if (i > 0) text += ', ';
          const placeholder = `$${placeholderCounter + 1}`;
          text += placeholder;
          resultValues.push(val[i]);
          placeholderCounter++;
        }
        text += ')';
      }
    } else {
      // Scalar value
      const placeholder = `$${placeholderCounter + 1}`;
      text += placeholder;
      resultValues.push(val);
      placeholderCounter++;
    }
  }

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      processValue(values[i]);
    }
  }

  return { text, values: resultValues };
}

