function createStore(reducer, initial) {
  let state = initial;
  const listeners = [];

  function getState() {
    return state;
  }

  function dispatch(action) {
    // Dispatching from inside a reducer must throw
    if (isDispatching) {
      throw new Error('Dispatching during reducer execution is not allowed.');
    }

    try {
      isDispatching = true;
      const newState = reducer(state, action);
      state = newState;
    } finally {
      isDispatching = false;
    }

    // Snapshot the listener list for this dispatch
    const currentListeners = listeners.slice();

    // Notify subscribers
    for (let i = 0; i < currentListeners.length; i++) {
      if (listeners.includes(currentListeners[i])) {
        currentListeners[i]();
      }
    }
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  let isDispatching = false;

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
