      detectCycleAndMissing(dep);
    }
    inStack.delete(name);
    visited.add(name);
  }

  // Validate all tasks first
  for (const name of taskNames) {
    try {
      detectCycleAndMissing(name);
    } catch (e) {
      return Promise.reject(e);
    }
  }

  // Execute tasks
  const executionPromises = taskNames.map(async (name) => {
    const task = tasks[name];
    const deps = task.deps || [];

    // Wait for all dependencies to resolve
    const depValues = {};
    const depPromises = deps.map(async (depName) => {
      const val = await results[depName];
      // If a dependency failed, this will throw, propagating the error
      return { name: depName, value: val };
    });

    try {
      const resolvedDeps = await Promise.all(depPromises);
      const depMap = {};
      for (const { name: depName, value } of resolvedDeps) {
        depMap[depName] = value;
      }

      // Run the task
      const value = await task.run(depMap);
      results[name] = value;
      return { name, value };
    } catch (e) {
      // If a dependency failed, we catch it here.
      // We need to ensure the error is propagated to the final result.
      // We store the error in a way that the final aggregation can pick it up.
      // However, since we are using Promise.all, if one fails, the whole thing fails.
      // But we need to ensure that tasks that don't depend on the failed task still run?
      // The prompt says: "If a task rejects, tasks that do not depend on it still complete, 
      // and the returned promise rejects with that error."
      // This implies we should run all tasks, collect results, and if any failed, reject with the error.
      // But wait, if a task depends on a failed task, it will also fail.
      // The key is: independent tasks must complete.

      // Let's restructure: We need to run all tasks. 
      // If a task fails, we record the error. 
      // If a task depends on a failed task, it will also fail (or we can catch and record).
      // The final promise should reject with the first error encountered? 
      // Or any error? "rejects with that error" implies the error from the failing task.

      // Let's use a different approach: 
      // 1. Build a dependency graph.
      // 2. Use a queue or recursive execution with memoization.
      // 3. If a task fails, mark it as failed.
      // 4. Tasks depending on a failed task will also fail.
      // 5. Independent tasks will succeed.
      // 6. Finally, if any task failed, reject with the error.

      // Since we are inside a map, we can't easily stop other tasks.
      // We need to catch errors per task and store them.
      throw e;
    }
  });

  // We need to handle the case where some tasks fail and some succeed.
  // The final promise should reject if ANY task failed.
  // But we must wait for all tasks to finish (or fail).

  // Let's rewrite the execution logic to be more robust.

  const finalResults = {};
  const finalErrors = [];

  // We'll use a recursive function with memoization
  const executing = new Set();
  const completed = new Set();
  const failed = new Set();

  async function runTask(name) {
    if (completed.has(name)) {
      return results[name];
    }
    if (failed.has(name)) {
      // We need to throw the error associated with this task.
      // But we don't store the error in `results`. 
      // Let's store errors in a separate map.
      throw finalErrors[name];
    }
    if (executing.has(name)) {
      // This shouldn't happen due to cycle detection, but just in case.
      throw new Error(`Cycle detected involving task: ${name}`);
    }

    executing.add(name);
    const task = tasks[name];
    const deps = task.deps || [];

    try {
      const depValues = {};
      for (const depName of deps) {
        // If a dependency failed, this will throw.
        const val = await runTask(depName);
        depValues[depName] = val;
      }

      const value = await task.run(depValues);
      results[name] = value;
      completed.add(name);
      executing.delete(name);
      return value;
    } catch (e) {
      failed.add(name);
      finalErrors[name] = e;
      executing.delete(name);
      throw e;
    }
  }

  // Run all tasks concurrently
  const allTaskPromises = taskNames.map(async (name) => {
    try {
      await runTask(name);
    } catch (e) {
      // We catch here to prevent Promise.all from short-circuiting immediately?
      // No, we want to wait for all tasks to finish.
      // But if we catch, we lose the error.
      // We need to know if ANY task failed.
      // Let's just let the errors bubble up to a final check.
      // But Promise.all rejects on the first error.
      // We need to wait for ALL tasks to complete, regardless of success/failure.
      // So we should not use Promise.all directly if we want to wait for all.
      // We can use Promise.allSettled.
    }
  });

  // Use Promise.allSettled to wait for all tasks
  return Promise.allSettled(allTaskPromises).then((results) => {
    // Check if any task failed
    const failedResult = results.find(r => r.status === 'rejected');
    if (failedResult) {
      return Promise.reject(failedResult.reason);
    }

    // If all succeeded, return the map of values
    const resultMap = {};
    taskNames.forEach(name => {
      resultMap[name] = results[name]; // This is wrong, results is an array of settlements
    });

    // Re-map correctly
    taskNames.forEach((name, index) => {
      resultMap[name] = results[index].value;
    });

    return resultMap;
  });
};
