export class Bus<E extends Record<string, unknown>> {
  private handlers: { [K in keyof E]?: Array<(payload: E[K]) => void> } = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers[k]) {
      this.handlers[k] = [];
    }
    this.handlers[k]!.push(fn);
    return () => {
      const index = this.handlers[k]!.indexOf(fn);
      if (index !== -1) {
        this.handlers[k]!.splice(index, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, payload: E[K]): void {
    const fns = this.handlers[k];
    if (fns) {
      for (const fn of fns) {
        fn(payload as any);
      }
    }
  }
}
