export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends object
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value === null || value === undefined) {
    return value as DeepAwaited<T>;
  }

  if (typeof value === 'function') {
    return value as unknown as DeepAwaited<T>;
  }

  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved) as Promise<DeepAwaited<T>>;
  }

  if (Array.isArray(value)) {
    const resolvedArray = await Promise.all(value.map((item) => deepAwait(item)));
    return resolvedArray as DeepAwaited<T>;
  }

  if (typeof value === 'object') {
    const keys = Object.keys(value);
    const resolvedObj: Record<string, unknown> = {};
    for (const key of keys) {
      resolvedObj[key] = await deepAwait((value as Record<string, unknown>)[key]);
    }
    return resolvedObj as DeepAwaited<T>;
  }

  return value as DeepAwaited<T>;
}
