export type Curry<F> = F extends (...args: infer A) => infer R
  ? (...args: infer B) => (B extends [...A] ? R : (
      ...rest: OmitArgs<A, B>
    ) => Curry<(...args: [...B, ...rest]) => R>)
  : never;

type OmitArgs<T extends any[], U extends any[]> = T extends [infer H, ...infer Rest]
  ? U extends [infer UH, ...infer UR]
    ? H extends UH
      ? OmitArgs<Rest, UR>
      : T
    : T
  : T;

export function curry<F extends (...args: any[]) => any>(fn: F): Curry<F> {
  return ((...args: any[]) => {
    if (args.length >= (fn as any).length) {
      return fn(...args);
    }
    return (...moreArgs: any[]) => curry(fn.bind(null, ...args, ...moreArgs));
  }) as any;
}
