export type Result<T, E> = Ok<T, E> | Err<T, E>;

export class Ok<T, E> {
  readonly kind = 'ok' as const;
  constructor(public readonly value: T) {}
}

export class Err<T, E> {
  readonly kind = 'err' as const;
  constructor(public readonly value: E) {}
}

export function ok<T, E>(value: T): Ok<T, E> {
  return new Ok(value);
}

export function err<T, E>(error: E): Err<T, E> {
  return new Err(error);
}

export function isOk<T, E>(r: Result<T, E>): r is Ok<T, E> {
  return r.kind === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is Err<T, E> {
  return r.kind === 'err';
}

export function map<T, U, E>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(fn(r.value));
  }
  return err(r.value);
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return fallback;
}
